 const change=async(next:string,reason='')=>{setSelected(next);setPending(true);try{await onChange(next,reason);return true}catch{setSelected(value);return false}finally{setPending(false)}};
 return <><select className="status-select" value={selected} disabled={pending} aria-busy={pending} onChange={e=>{const next=e.target.value;if(['중도탈락','취소'].includes(next))setReasonStatus(next);else void change(next)}}>{['신청','선정검토','참가대기','참가중','참가완료','중도탈락','취소'].map(s=><option key={s}>{s}</option>)}</select>{reasonStatus&&<StatusReasonModal status={reasonStatus} onClose={()=>setReasonStatus(null)} onSubmit={async reason=>{if(await change(reasonStatus,reason))setReasonStatus(null)}}/>}</>
