      const result=await response.json() as ScopedAttendance&{error?:string;loginRequired?:boolean};
      if(!response.ok){if(result.loginRequired||response.status===401)sessionExpiredRef.current();throw new Error(result.error||'출석 상세정보를 불러오지 못했습니다.');}
