  const closed=session?.attendance_status==='마감',missingCount=detailReady?apps.filter(a=>statusOf(a.id)==='미입력').length:0,contactMode=data.currentUser?.role==='관리자'?'raw':data.currentUser?.role==='일반 담당자'?'detail':'none';
  const reloadAfter=async(targetSessionId:string,targetRunId:string,mutation:()=>Promise<void>)=>{await mutation();const current=currentAttendanceScope.current;if(isStaff&&current.sessionId===targetSessionId&&current.runId===targetRunId)await loadSessionAttendance(targetSessionId,targetRunId,true)};
