function Certificates({data,selected,setSelected,center,onIssue}:{data:Data;selected:Participant|null;setSelected:(p:Participant|null)=>void;center:string;onIssue:(p:Participant,c:number)=>void}){const [q,setQ]=useState('');const people=data.participants.filter(p=>`${p.name}${p.id}`.includes(q));const rows=selected?data.attendance.filter(a=>a.participant_id===selected.id&&['참석','보강'].includes(a.status)):[];return <><div className="no-print"><Heading title="참여확인서 발급" desc="참석과 보강으로 확인된 회기만 확인서에 표시됩니다."/><div className="certificate-layout"><section className="panel certificate-search"><div className="table-search">⌕ <input value={q} onChange={e=>setQ(e.target.value)} placeholder="참가자 검색"/></div>{people.map(p=><button className={selected?.id===p.id?'active':''} onClick={()=>setSelected(p)} key={p.id}><span className="person-avatar tone-1">{p.name.slice(-1)}</span><span><b>{p.name}</b><small>{p.id} · 참여 {p.attended_count}회</small></span></button>)}</section><section className="certificate-wrap">{selected?<CertificatePaper center={center} person={selected} rows={rows}/>:<Empty text="참가자를 선택하세요."/>}</section></div>{selected&&<div className="certificate-actions"><button className="primary-button" disabled={!rows.length} onClick={()=>onIssue(selected,rows.length)}>발급 이력 저장 후 인쇄</button></div>}</div>{selected&&<div className="print-only"><CertificatePaper center={center} person={selected} rows={rows}/></div>}</>}
function CertificatePaper({center,person,rows}:{center:string;person:Participant;rows:AttendanceRow[]}){return <article className="certificate-paper"><div className="cert-mark">확인</div><h1>프로그램 참여확인서</h1><div className="cert-person"><span>성명 <b>{person.name}</b></span><span>관리번호 <b>{person.id}</b></span></div><table><thead><tr><th>참여일</th><th>프로그램 / 차수</th><th>회기</th><th>구분</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{fmt(r.session_date)}</td><td>{r.program_name} · {r.run_label}</td><td>{r.session_number}회기</td><td>{r.status}</td></tr>)}</tbody></table><p className="cert-statement">위 사람은 상기 프로그램에 참여하였음을 확인합니다.</p><p className="cert-date">{new Date().toLocaleDateString('ko-KR')}</p><div className="cert-sign"><b>{center}장</b><i>직인</i></div></article>}

function AuditHistory({logs}:{logs:AuditLog[]}){return <><Heading title="변경·조회 이력" desc="애플리케이션에서 누가 언제 어떤 기록을 변경·조회했는지 확인합니다."/><Table><thead><tr><th>일시</th><th>담당자</th><th>작업</th><th>대상</th><th>내용·사유</th><th>접속</th><th>변경 전후</th></tr></thead><tbody>{logs.map(log=><tr key={log.id}><td>{log.created_at}</td><td><b>{log.actor_display_name?`${log.actor_display_name} · ${log.actor}`:log.actor}</b></td><td>{log.action}</td><td>{log.entity_type} · {log.entity_id}</td><td>{log.summary}{log.reason&&<small className="sub-id">사유: {log.reason}</small>}</td><td>{log.ip_address||'local'}</td><td><details className="audit-detail"><summary>확인</summary><div><b>변경 전</b><pre>{log.before_json||'-'}</pre><b>변경 후</b><pre>{log.after_json||'-'}</pre></div></details></td></tr>)}</tbody></Table>{!logs.length&&<Empty text="아직 기록된 변경 이력이 없습니다."/>}</>}
function UserManagement({users,currentUser,onCreate,onUpdate}:{users:StaffUser[];currentUser:StaffUser|null;onCreate:(f:Record<string,unknown>)=>void;onUpdate:(f:Record<string,unknown>)=>void}){return <section className="panel settings-card user-management"><h2>직원 계정 및 권한</h2><p>현재 로그인: <b>{currentUser?.display_name}</b> · {currentUser?.role}</p><div className="user-list">{users.map(user=><UserEditor key={user.id} user={user} onUpdate={onUpdate}/>)}</div><form className="user-add" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onCreate(Object.fromEntries(f));e.currentTarget.reset()}}><input name="username" placeholder="로그인 계정" required/><input name="displayName" placeholder="직원 이름" required/><input name="pin" type="password" inputMode="numeric" placeholder="PIN 6자리 이상" minLength={6} required/><select name="role"><option>일반 담당자</option><option>출석 입력 전용</option><option>관리자</option></select><button>직원 추가</button></form></section>}
function UserEditor({user,onUpdate}:{user:StaffUser;onUpdate:(f:Record<string,unknown>)=>void}){const [name,setName]=useState(user.display_name),[role,setRole]=useState(user.role),[active,setActive]=useState(Boolean(user.active)),[pin,setPin]=useState('');const locked=Boolean(user.locked_until&&new Date(user.locked_until)>new Date());return <div className={`user-editor ${locked?'locked':''}`}><span><b>{user.username}</b><small>{user.id} · 최근 로그인 {user.last_login_at?new Date(user.last_login_at).toLocaleString('ko-KR'):'없음'}</small>{locked&&<em>{new Date(user.locked_until!).toLocaleTimeString('ko-KR')}까지 잠김</em>}{Boolean(user.must_change_pin)&&<em>PIN 변경 필요</em>}</span><input value={name} onChange={e=>setName(e.target.value)}/><select value={role} onChange={e=>setRole(e.target.value)}><option>관리자</option><option>일반 담당자</option><option>출석 입력 전용</option></select><input value={pin} onChange={e=>setPin(e.target.value)} type="password" placeholder="새 PIN 6자리(선택)"/><label><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>사용</label><button onClick={()=>{onUpdate({id:user.id,displayName:name,role,active,pin});setPin('')}}>저장</button></div>}
function PinChange({required,onChange}:{required:boolean;onChange:(currentPin:string,newPin:string)=>void}){return <form className={`panel settings-card pin-change ${required?'required':''}`} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),currentPin=String(f.get('currentPin')),newPin=String(f.get('newPin')),confirmPin=String(f.get('confirmPin'));if(newPin!==confirmPin){window.alert('새 PIN 확인이 일치하지 않습니다.');return}onChange(currentPin,newPin);e.currentTarget.reset()}}><h2>내 PIN 변경 {required&&<em>필수</em>}</h2><p>반복 숫자가 아닌 6자리 이상으로 설정하세요.</p><label>현재 PIN<input name="currentPin" type="password" inputMode="numeric" required/></label><label>새 PIN<input name="newPin" type="password" inputMode="numeric" minLength={6} required/></label><label>새 PIN 확인<input name="confirmPin" type="password" inputMode="numeric" minLength={6} required/></label><button className="primary-button">PIN 변경</button></form>}
function Settings({data,onSave,onBackup,onCheck,onRestore,onCreateUser,onUpdateUser,onChangePin}:{data:Data;onSave:(c:string,m:string)=>void;onBackup:()=>void;onCheck:(basename:string)=>void;onRestore:(basename:string)=>void;onCreateUser:(f:Record<string,unknown>)=>void;onUpdateUser:(f:Record<string,unknown>)=>void;onChangePin:(currentPin:string,newPin:string)=>void}){const [backupBasename,setBackupBasename]=useState(data.backupFiles[0]?.basename||'');useEffect(()=>{if(backupBasename&&!data.backupFiles.some(file=>file.basename===backupBasename))setBackupBasename(data.backupFiles[0]?.basename||'');else if(!backupBasename&&data.backupFiles[0])setBackupBasename(data.backupFiles[0].basename)},[data.backupFiles,backupBasename]);const selectedBackup=data.backupFiles.find(file=>file.basename===backupBasename),restoreCompatible=selectedBackup?.purpose==='manual'||selectedBackup?.purpose==='restore_safety';return <><Heading title="설정" desc="센터 정보, 직원 권한, 로컬 데이터 파일과 분리 백업을 관리합니다."/><div className="settings-grid"><form className="panel settings-card" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave(String(f.get('centerName')),String(f.get('managerName')))}}><h2>센터 정보</h2><label>센터 이름<input name="centerName" defaultValue={data.settings.center_name}/></label><label>기본 담당자 표시명<input name="managerName" defaultValue={data.settings.manager_name}/></label><button className="primary-button">설정 저장</button></form><section className="panel settings-card storage-card"><h2>데이터 저장 구조</h2><span className="storage-state">● 단일 서버·로컬 DB</span><p>실시간 DB는 서버 PC에, 검증된 백업은 분리 보관합니다.</p><label>운영 DB<code className="db-path">로컬 데이터베이스</code></label><label>백업 상태<code className="db-path">서버 관리 백업 폴더</code></label><small>{data.storageInfo?.architecture||'로컬 단일 서버'} · Journal {data.storageInfo?.journalMode||'DELETE'}</small><button className="secondary-button" onClick={onBackup}>검증된 백업 만들기</button></section><PinChange required={Boolean(data.currentUser?.must_change_pin)} onChange={onChangePin}/><UserManagement users={data.users} currentUser={data.currentUser} onCreate={onCreateUser} onUpdate={onUpdateUser}/><section className="panel settings-card backup-restore"><h2>백업 점검 및 복원</h2><p>복원 전 SHA-256, SQLite, FK, 스키마를 점검하고 현재 데이터의 안전 백업을 먼저 생성합니다.</p><label>검증된 백업 파일<select value={backupBasename} onChange={e=>setBackupBasename(e.target.value)}><option value="">백업 파일 선택</option>{data.backupFiles.map(file=><option key={file.basename} value={file.basename}>{file.basename} · {file.purpose}{file.purpose==='migration_safety'?' (복원 불가)':''} · {(file.size/1024).toFixed(0)}KB</option>)}</select></label><div><button className="secondary-button" disabled={!backupBasename} onClick={()=>onCheck(backupBasename)}>무결성 점검</button><button className="danger-button" disabled={!restoreCompatible} onClick={()=>{if(window.confirm('선택한 백업으로 현재 데이터를 복원할까요? 복원 후 다시 로그인해야 합니다.'))onRestore(backupBasename)}}>선택 백업 복원</button></div>{selectedBackup?.purpose==='migration_safety'&&<small>스키마 마이그레이션 안전 백업은 일반 데이터 복원에 사용할 수 없습니다.</small>}{!data.backupFiles.length&&<small>아직 검증된 백업 파일이 없습니다.</small>}</section><section className="panel settings-card security-card"><h2>내부망 운영 안내</h2><ul><li>외장하드는 서버 PC 한 대에만 연결하고 공유 폴더에는 백업만 두세요.</li><li>직원별 계정과 PIN을 공유하지 마세요.</li><li>복원 중에는 다른 직원의 입력을 중단하세요.</li><li>외장하드 암호화와 복원 훈련을 정기적으로 실시하세요.</li></ul></section></div></>}

function LoginModal({users,currentUser,onClose,onLogin,onLogout}:{users:StaffUser[];currentUser:StaffUser|null;onClose:()=>void;onLogin:(username:string,pin:string)=>Promise<void>;onLogout:()=>Promise<void>}){const [username,setUsername]=useState(''),[pin,setPin]=useState(''),[submitting,setSubmitting]=useState(false);return <div className="modal-backdrop"><form className="modal login-modal" onSubmit={async e=>{e.preventDefault();if(submitting)return;setSubmitting(true);try{await onLogin(username,pin)}finally{setSubmitting(false)}}}><div className="login-mark">봄</div><h2>{currentUser?'작업자 전환':'직원 로그인'}</h2><p>변경 이력에는 로그인한 직원 이름·시간·접속 위치가 기록됩니다.</p>{users.length>0?<label>직원 계정<select disabled={submitting} value={username} onChange={e=>setUsername(e.target.value)} required><option value="">계정 선택</option>{users.filter(user=>user.active).map(user=><option key={user.id} value={user.username}>{user.display_name} · {user.role}{user.locked_until&&new Date(user.locked_until)>new Date()?' · 잠김':''}</option>)}</select></label>:<label>계정<input disabled={submitting} value={username} onChange={e=>setUsername(e.target.value)} placeholder="직원 계정" required/></label>}<label>PIN<input disabled={submitting} type="password" inputMode="numeric" value={pin} onChange={e=>setPin(e.target.value)} placeholder="PIN 입력" required/></label><button disabled={submitting} className="primary-button">{submitting?'로그인 확인 중…':'로그인'}</button>{submitting&&<div className="login-progress"><i/>로컬 데이터베이스에서 계정을 확인하고 있습니다.</div>}{currentUser&&<div className="login-secondary"><button type="button" onClick={onClose}>취소</button><button type="button" onClick={()=>void onLogout()}>로그아웃</button></div>} {!currentUser&&<small>최초 관리자는 서버의 bootstrap 환경설정으로 한 번만 생성됩니다.</small>}</form></div>}
function PersonModal({person,data,onClose,onCertificate}:{person:Participant;data:Data;onClose:()=>void;onCertificate:()=>void}){const apps=data.applications.filter(a=>a.participant_id===person.id);const att=data.attendance.filter(a=>a.participant_id===person.id);return <div className="modal-backdrop" onMouseDown={onClose}><section className="modal history-modal" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="profile-head"><span className="person-avatar tone-0">{person.name.slice(-1)}</span><div><h2>{person.name}</h2><p>{person.id} · {person.gender} · {person.age}세 · {person.member_status}</p><p>{person.phone}</p></div></div><div className="profile-note"><b>메모</b><p>{person.note||'등록된 메모가 없습니다.'}</p></div><h3>신청 프로그램 <span>{apps.length}건</span></h3><div className="history-list">{apps.map(a=><article key={a.id}><time>{fmt(a.start_date)}<small>{a.run_label}</small></time><div><b>{a.program_name}</b><span>{a.delivery_type} · 출석 {att.filter(x=>x.run_id===a.run_id&&['참석','보강'].includes(x.status)).length}/{a.session_count}회</span></div><i className="attendance-tag 신청">{a.status}</i></article>)}</div><div className="modal-actions"><button className="secondary-button" onClick={onClose}>닫기</button><button className="primary-button" onClick={onCertificate}>참여확인서</button></div></section></div>}
function StatusReasonModal({status,onClose,onSubmit}:{status:string;onClose:()=>void;onSubmit:(reason:string)=>Promise<void>}){const [reason,setReason]=useState(''),[error,setError]=useState(''),[saving,setSaving]=useState(false);return <div className="modal-backdrop" onMouseDown={onClose}><form className="modal form-modal" onMouseDown={event=>event.stopPropagation()} onSubmit={async event=>{event.preventDefault();const trimmed=reason.trim();if(!trimmed){setError(`${status} 사유를 입력하세요.`);return}setSaving(true);try{await onSubmit(trimmed)}finally{setSaving(false)}}}><button type="button" className="modal-close" onClick={onClose}>×</button><h2>{status} 사유</h2><p>상태를 변경하려면 사유를 기록해야 합니다.</p><label className="full">사유<textarea autoFocus value={reason} onChange={event=>{setReason(event.target.value);setError('')}} placeholder="사유를 입력하세요." required/></label>{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="secondary-button" disabled={saving} onClick={onClose}>취소</button><button className="primary-button" disabled={saving}>{saving?'저장 중…':'상태 변경'}</button></div></form></div>}
function ImportRejectModal({result,programs,retryRowCount,onRetry,onClose}:{result:ImportResult;programs:Program[];retryRowCount:number;onRetry:(programId:string)=>Promise<void>;onClose:()=>void}){const [programId,setProgramId]=useState(''),[saving,setSaving]=useState(false);const canRetry=retryRowCount>0;return <div className="modal-backdrop" onMouseDown={onClose}><section className="modal form-modal" onMouseDown={event=>event.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><h2>Excel 가져오기 제외 사유</h2><p>제외 {result.rejectedCount}건입니다. 개인정보는 표시하지 않습니다.</p><ul>{result.rejectedRows.map(item=><li key={`${item.rowNumber}-${item.reason}`}>{item.rowNumber}행 · {item.reason}</li>)}</ul>{canRetry&&<form onSubmit={async event=>{event.preventDefault();if(!programId)return;setSaving(true);try{await onRetry(programId)}finally{setSaving(false)}}}><label className="full">프로그램명이 비어 있는 {retryRowCount}건의 프로그램 선택<select value={programId} onChange={event=>setProgramId(event.target.value)} required><option value="">프로그램을 선택하세요</option>{programs.map(program=><option key={program.id} value={program.id}>{program.name}</option>)}</select></label><div className="modal-actions"><button className="primary-button" disabled={!programId||saving}>{saving?'등록 중…':'선택한 프로그램으로 등록'}</button></div></form>}<div className="modal-actions"><button className="secondary-button" onClick={onClose}>닫기</button></div></section></div>}
function Modal({title,onClose,onSubmit,children}:{title:string;onClose:()=>void;onSubmit:(e:FormEvent<HTMLFormElement>)=>void;children:React.ReactNode}){return <div className="modal-backdrop" onMouseDown={onClose}><form className="modal form-modal" onSubmit={onSubmit} onMouseDown={e=>e.stopPropagation()}><button type="button" className="modal-close" onClick={onClose}>×</button><h2>{title}</h2>{children}<div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>취소</button><button className="primary-button">저장하기</button></div></form></div>}
function ParticipantModal({data,onClose,onSubmit}:{data:Data;onClose:()=>void;onSubmit:(f:Record<string,string>)=>void}){return <Modal title="새 참가자 등록" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>)}}><div className="form-grid"><label>이름<input name="name" required/></label><label>성별<select name="gender"><option>여성</option><option>남성</option><option>기타</option><option>미입력</option></select></label><label>나이<input name="age" type="number" min="0" max="120" required/></label><label>연락처<input name="phone" placeholder="010-0000-0000" required/></label><label>회원 여부<select name="memberStatus"><option>회원</option><option>비회원</option><option>휴면</option></select></label><label>신청 프로그램<select name="runId"><option value="">신청 안 함</option>{data.runs.map(r=><option value={r.id} key={r.id}>{r.program_name} · {r.label}</option>)}</select></label><label className="full">메모<textarea name="note" placeholder="업무에 필요한 내용만 입력하세요."/></label></div></Modal>}
function ParticipantModalV2({data,onClose,onSubmit}:{data:Data;onClose:()=>void;onSubmit:(f:Record<string,unknown>)=>void}){const [programIds,setProgramIds]=useState<string[]>([]),[phone,setPhone]=useState('');const toggle=(id:string)=>setProgramIds(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);return <Modal title="새 참가자 등록" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit({...Object.fromEntries(new FormData(e.currentTarget)),programIds})}}><div className="form-grid"><label>이름<input name="name" required/></label><label>성별<select name="gender"><option>여성</option><option>남성</option><option>기타</option><option>미입력</option></select></label><label>나이<input name="age" type="number" min="0" max="120" required/></label><label>연락처<input name="phone" inputMode="tel" autoComplete="tel" value={phone} onChange={e=>setPhone(formatKoreanPhoneInput(e.target.value))} placeholder="010-0000-0000" required/></label><label>회원 여부<select name="memberStatus"><option>회원</option><option>비회원</option><option>휴면</option></select></label><div className="full program-multiselect"><b>신청 프로그램 <small>복수 선택 가능 · 차수는 나중에 배정</small></b><div>{data.programs.map(p=><label className={programIds.includes(p.id)?'checked':''} key={p.id}><input type="checkbox" checked={programIds.includes(p.id)} onChange={()=>toggle(p.id)}/><span>{p.name}</span><em>{p.delivery_type} · {p.session_count}회기</em></label>)}</div>{!programIds.length&&<p>선택하지 않으면 참가자 정보만 등록됩니다.</p>}</div><label className="full">메모<textarea name="note" placeholder="업무에 필요한 내용만 입력하세요."/></label></div></Modal>}
function EditParticipantModal({person,onClose,onSubmit}:{person:ParticipantDetail;onClose:()=>void;onSubmit:(f:Record<string,string>)=>void}){const [phone,setPhone]=useState(person.phone);return <Modal title="참가자 정보 수정" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>)}}><input type="hidden" name="id" value={person.id}/><div className="form-grid"><label>이름<input name="name" defaultValue={person.name} required/></label><label>성별<select name="gender" defaultValue={person.gender}><option>여성</option><option>남성</option><option>기타</option><option>미입력</option></select></label><label>나이<input name="age" type="number" min="0" max="120" defaultValue={person.age} required/></label><label>연락처<input name="phone" value={phone} onChange={e=>setPhone(formatKoreanPhoneInput(e.target.value))} inputMode="tel" autoComplete="tel" placeholder="010-0000-0000" required/></label><label>회원 여부<select name="memberStatus" defaultValue={person.member_status}><option>회원</option><option>비회원</option><option>휴면</option></select></label><label className="full">메모<textarea name="note" defaultValue={person.note} placeholder="업무에 필요한 내용만 입력하세요."/></label></div></Modal>}
function ProgramModal({onClose,onSubmit}:{onClose:()=>void;onSubmit:(f:Record<string,string>)=>void}){const [type,setType]=useState('집단');return <Modal title="새 프로그램 등록" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>)}}><div className="form-grid"><label className="full">프로그램명<input name="name" required/></label><label>운영 형태<select name="deliveryType" value={type} onChange={e=>setType(e.target.value)}><option>집단</option><option>1:1</option></select></label><label>분류<input name="category" placeholder="정서회복, 개별상담 등" required/></label><label>총 회기 수<input name="sessionCount" type="number" min="1" defaultValue="3" required/></label><label>회기 간격<select name="recurrence"><option>매주</option><option>매월</option><option>매일</option></select></label><label>정원<input name="capacity" type="number" min="1" defaultValue={type==='1:1'?1:10} disabled={type==='1:1'}/></label><label>담당자<input name="manager" required/></label><label>장소<input name="location" required/></label><label>첫 차수 이름<input name="runLabel" placeholder="예: 2026년 9월 1차" required/></label><label>첫 회기 날짜<input name="startDate" type="date" required/></label><label>시간<input name="time" type="time" required/></label></div></Modal>}
function RunModal({data,initialProgramId,onClose,onSubmit}:{data:Data;initialProgramId?:string;onClose:()=>void;onSubmit:(f:Record<string,string>)=>void}){return <Modal title="새 차수 만들기" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>)}}><div className="form-grid"><label className="full">프로그램<select name="programId" defaultValue={initialProgramId||data.programs[0]?.id}>{data.programs.map(p=><option value={p.id} key={p.id}>{p.name} · {p.session_count}회기</option>)}</select></label><label className="full">차수 이름<input name="label" placeholder="예: 2026년 10월 3차" required/></label><label>첫 회기 날짜<input name="startDate" type="date" required/></label><label>시간<input name="time" type="time" required/></label></div></Modal>}
function ApplyModal({data,onClose,onSubmit}:{data:Data;onClose:()=>void;onSubmit:(f:Record<string,string>)=>void}){return <Modal title="신청자 추가" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>)}}><div className="form-grid"><label className="full">참가자<select name="participantId">{data.participants.map(p=><option value={p.id} key={p.id}>{p.name} · {p.id}</option>)}</select></label><label className="full">프로그램 · 차수<select name="runId">{data.runs.map(r=><option value={r.id} key={r.id}>{r.program_name} · {r.label} · {fmt(r.start_date)}</option>)}</select></label></div></Modal>}
