function EditProgramModal({program,onClose,onSubmit}:{program:Program;onClose:()=>void;onSubmit:(f:Record<string,string>)=>void}){const [type,setType]=useState(program.delivery_type);return <Modal title="프로그램 수정" onClose={onClose} onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>)}}><input type="hidden" name="id" value={program.id}/><div className="form-grid"><label className="full">프로그램명<input name="name" defaultValue={program.name} required/></label><label>운영 형태<select name="deliveryType" value={type} onChange={e=>setType(e.target.value)}><option>집단</option><option>1:1</option></select></label><label>분류<input name="category" defaultValue={program.category} required/></label><label>고정 회기 수<input value={`${program.session_count}회기`} disabled/><small>회기 수는 기존 기록 보호를 위해 고정됩니다.</small></label><label>정원<input name="capacity" type="number" min="1" defaultValue={type==='1:1'?1:program.capacity} disabled={type==='1:1'}/></label><label>담당자<input name="manager" defaultValue={program.manager} required/></label><label>장소<input name="location" defaultValue={program.location} required/></label><label>운영 상태<select name="status" defaultValue={program.status}><option>운영 중</option><option>운영 종료</option><option>일시 중단</option></select></label></div></Modal>}

function CopyProgramModal({program,onClose,onSubmit}:{program:Program;onClose:()=>void;onSubmit:(name:string)=>Promise<void>}){const [name,setName]=useState(`${program.name} - 복사본`),[saving,setSaving]=useState(false),[error,setError]=useState('');return <div className="modal-backdrop" onMouseDown={onClose}><form className="modal form-modal" onMouseDown={event=>event.stopPropagation()} onSubmit={async event=>{event.preventDefault();if(!name.trim()){setError('새 프로그램명을 입력하세요.');return}setSaving(true);try{await onSubmit(name.trim())}catch{setError('프로그램 복사에 실패했습니다.')}finally{setSaving(false)}}}><button type="button" className="modal-close" onClick={onClose}>×</button><h2>프로그램 복사</h2><p>운영 설정과 검사 구성만 복사합니다. 차수와 참가자 기록은 복사하지 않습니다.</p><label className="full">새 프로그램명<input autoFocus value={name} onChange={event=>{setName(event.target.value);setError('')}} required/></label>{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="secondary-button" disabled={saving} onClick={onClose}>취소</button><button className="primary-button" disabled={saving}>{saving?'복사 중…':'프로그램 복사'}</button></div></form></div>}function ProgramManageModal({program,data,onContact,onClose,onAssign,onAddToRun,onSessionsBulk,onCopyRun,onUpdateRun,onRemoveFromRun,onDeleteRun,onRunStatus}:{program:Program;data:Data;onContact:(participantId:string)=>void;onClose:()=>void;onAssign:(applicationId:number,runId:string)=>void;onAddToRun:(participantId:string,runId:string)=>void;onSessionsBulk:(runId:string,sessions:{id:string;sessionDate:string;sessionTime:string;location:string}[])=>Promise<void>;onCopyRun:(runId:string)=>Promise<void>;onUpdateRun:(id:string,label:string)=>Promise<void>;onRemoveFromRun:(applicationId:number,runId:string)=>Promise<void>;onDeleteRun:(id:string)=>Promise<void>;onRunStatus:(id:string,status:string)=>void}){
 const [drafts,setDrafts]=useState<Record<string,{sessionDate:string;sessionTime:string;location:string}>>({}),[runLabels,setRunLabels]=useState<Record<string,string>>({}),[savingRun,setSavingRun]=useState<string|null>(null);const runs=data.runs.filter(r=>r.program_id===program.id).sort((a,b)=>a.round_number-b.round_number),applications=data.applications.filter(a=>a.program_id===program.id),unassigned=applications.filter(a=>!a.run_id),available=data.participants.filter(p=>!applications.some(a=>a.participant_id===p.id));const edit=(session:Session,field:'sessionDate'|'sessionTime'|'location',value:string)=>setDrafts(current=>({...current,[session.id]:{...(current[session.id]||{sessionDate:session.session_date,sessionTime:session.session_time,location:session.location}),[field]:value}}));const dirty=(session:Session)=>{const value=drafts[session.id];return value&&`${value.sessionDate}|${value.sessionTime}|${value.location}`!==`${session.session_date}|${session.session_time}|${session.location}`};const saveRun=async(runId:string,sessions:Session[])=>{const changed=sessions.filter(dirty).map(session=>({id:session.id,...drafts[session.id]}));if(!changed.length)return;setSavingRun(runId);try{await onSessionsBulk(runId,changed);setDrafts(current=>{const next={...current};for(const session of sessions)delete next[session.id];return next})}finally{setSavingRun(null)}};
 return <div className="modal-backdrop" onMouseDown={onClose}><section className="modal manage-modal" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="manage-title"><span className={`type-badge ${program.delivery_type==='1:1'?'one':'group'}`}>{program.delivery_type}</span><div><h2>{program.name}</h2><p>{program.session_count}회기 · 신청 {applications.length}명 · {runs.length}개 차수</p></div></div><section className="unassigned-box"><h3>차수 미배정 신청자 <b>{unassigned.length}명</b></h3>{unassigned.map(a=><div className="assignment-row" key={a.id}><span><b>#{a.queue_number} {a.participant_name}</b><small>{a.participant_id} · {a.status} · <button className="text-button" onClick={()=>onContact(a.participant_id)}>연락처 보기</button></small></span><select defaultValue="" onChange={e=>{if(e.target.value)onAssign(a.id,e.target.value)}}><option value="">배정할 차수 선택</option>{runs.filter(r=>!['종료','취소'].includes(r.status)).map(r=><option key={r.id} value={r.id}>{r.label} · {r.status} · {fmt(r.start_date)}</option>)}</select></div>)}{!unassigned.length&&<p>차수 배정을 기다리는 신청자가 없습니다.</p>}</section><div className="run-manage-list">{runs.map(r=>{const assigned=applications.filter(a=>a.run_id===r.id),sessions=data.sessions.filter(s=>s.run_id===r.id).sort((a,b)=>a.session_number-b.session_number),locked=['종료','취소'].includes(r.status),dirtyCount=sessions.filter(dirty).length;return <section className={`run-manage-card ${assigned.length>r.capacity?'capacity-over':''} ${locked?'run-closed':''}`} key={r.id}><header><div><div className="run-label-edit"><input aria-label="차수 이름" value={runLabels[r.id]??r.label} onChange={e=>setRunLabels(current=>({...current,[r.id]:e.target.value}))}/><button disabled={savingRun===r.id||(runLabels[r.id]??r.label)===r.label} onClick={()=>void onUpdateRun(r.id,runLabels[r.id]??r.label)}>이름 저장</button></div><p>{assigned.length}/{r.capacity}명 배정 {assigned.length>=r.capacity&&<b>· 정원 도달 — 추가 시 경고</b>}</p>{r.closed_at&&<small>{new Date(r.closed_at).toLocaleString('ko-KR')} · {r.closed_by}</small>}</div><div className="run-actions"><button className="secondary-button" disabled={savingRun===r.id} onClick={()=>void onCopyRun(r.id)}>차수 복사</button><button className="danger-button" disabled={savingRun===r.id} onClick={()=>{if(!window.confirm('차수를 삭제할까요? 배정된 신청자는 미배정으로 남습니다.'))return;if(!window.confirm('두 번째 확인: 회기와 해당 차수의 출석 기록은 삭제됩니다. 계속할까요?'))return;void onDeleteRun(r.id)}}>차수 삭제</button><select className="run-status-select" value={r.status} onChange={e=>onRunStatus(r.id,e.target.value)}>{['모집 예정','모집 중','모집 마감','참가자 확정','진행 중','종료','취소'].map(status=><option key={status}>{status}</option>)}</select></div></header>{!locked&&<RunApplicantAdder participants={available} run={r} overCapacity={assigned.length>=r.capacity} onAdd={onAddToRun}/>}<div className="assigned-people">{assigned.map(a=><span key={a.id}><b>{a.participant_name}</b><small>{a.participant_id} · {a.status} · <button className="text-button" onClick={()=>onContact(a.participant_id)}>연락처 보기</button></small><button className="text-button danger-text" onClick={()=>{if(window.confirm('이 신청자를 이 차수에서 제거할까요? 참가자 정보와 프로그램 신청은 유지됩니다.'))void onRemoveFromRun(a.id,r.id)}}>신청자 삭제</button></span>)}{!assigned.length&&<em>배정된 신청자가 없습니다.</em>}</div><div className="session-bulk-head"><h4>회기 일정 <small>날짜·시간·장소 변경 후 한 번에 저장</small></h4><button disabled={!dirtyCount||savingRun===r.id} onClick={()=>void saveRun(r.id,sessions)}>{savingRun===r.id?'저장 중…':`변경사항 ${dirtyCount}건 일괄 저장`}</button></div>{sessions.map(s=><SessionEditor key={s.id} session={s} value={drafts[s.id]||{sessionDate:s.session_date,sessionTime:s.session_time,location:s.location}} dirty={Boolean(dirty(s))} onChange={edit}/>)}</section>})}</div><div className="modal-actions"><button className="primary-button" onClick={onClose}>확인</button></div></section></div>
}function RunApplicantAdder({participants,run,overCapacity,onAdd}:{participants:Participant[];run:Run;overCapacity:boolean;onAdd:(participantId:string,runId:string)=>void}){const [participantId,setParticipantId]=useState('');useEffect(()=>{if(participantId&&!participants.some(p=>p.id===participantId))setParticipantId('')},[participants,participantId]);return <div className={`run-add-applicant ${overCapacity?'warning':''}`}><label>이 차수에 신청자 추가 {overCapacity&&<small>정원 초과 경고</small>}</label><select aria-label={`${run.label} 신청자 선택`} value={participantId} disabled={!participants.length} onChange={e=>setParticipantId(e.target.value)}><option value="">기존 참가자 선택</option>{participants.map(p=><option key={p.id} value={p.id}>{p.name} · {p.id}</option>)}</select><button disabled={!participantId} onClick={()=>{onAdd(participantId,run.id);setParticipantId('')}}>{overCapacity?'경고 후 추가':'추가'}</button></div>}
function SessionEditor({session,value,dirty,onChange}:{session:Session;value:{sessionDate:string;sessionTime:string;location:string};dirty:boolean;onChange:(session:Session,field:'sessionDate'|'sessionTime'|'location',value:string)=>void}){return <div className={`session-editor ${dirty?'dirty':''}`}><b>{session.session_number}회기 {dirty&&<small>변경됨</small>}</b><input aria-label={`${session.session_number}회기 날짜`} type="date" value={value.sessionDate} onChange={e=>onChange(session,'sessionDate',e.target.value)}/><input aria-label={`${session.session_number}회기 시간`} type="time" value={value.sessionTime} onChange={e=>onChange(session,'sessionTime',e.target.value)}/><input aria-label={`${session.session_number}회기 장소`} value={value.location} onChange={e=>onChange(session,'location',e.target.value)}/></div>}
function AccountSettings({user,onChangePin}:{user:StaffUser|null;onChangePin:(currentPin:string,newPin:string)=>void}){return <><Heading title="내 계정" desc="본인 계정과 PIN을 안전하게 관리합니다."/><div className="settings-grid account-only"><section className="panel settings-card"><h2>로그인 정보</h2><p><b>{user?.display_name}</b> · {user?.role}</p><p>계정 {user?.username} · 최근 로그인 {user?.last_login_at?new Date(user.last_login_at).toLocaleString('ko-KR'):'-'}</p>{Boolean(user?.must_change_pin)&&<span className="storage-state">PIN 변경 필요</span>}</section><PinChange required={Boolean(user?.must_change_pin)} onChange={onChangePin}/></div></>}
function PhoneSearch({onSelect,onSessionExpired}:{onSelect:(participantId:string)=>void;onSessionExpired:()=>void}){const [phone,setPhone]=useState(''),[results,setResults]=useState<PhoneSearchResult[]>([]),[loading,setLoading]=useState(false),[searched,setSearched]=useState(false),[error,setError]=useState('');const requestAbort=useRef<AbortController|null>(null),requestValue=useRef('');const search=async()=>{const normalized=phone.replace(/\D/g,'');if(!/^\d{10,11}$/.test(normalized)){setResults([]);setSearched(false);setError('전화번호 전체 10~11자리를 입력하세요.');return}requestAbort.current?.abort();const controller=new AbortController();requestAbort.current=controller;requestValue.current=normalized;setLoading(true);setSearched(false);setError('');try{const response=await fetch('/api/data',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'participantPhoneSearch',phone}),signal:controller.signal});const body=await response.json() as {results?:PhoneSearchResult[];error?:string;loginRequired?:boolean};if(!response.ok){if(body.loginRequired||response.status===401)onSessionExpired();throw new Error(body.error||'전화번호를 검색하지 못했습니다.')}if(controller.signal.aborted||requestAbort.current!==controller||requestValue.current!==normalized)return;setResults(body.results||[]);setSearched(true)}catch(searchError){if(controller.signal.aborted||searchError instanceof Error&&searchError.name==='AbortError')return;if(requestAbort.current===controller){setResults([]);setSearched(false);setError(searchError instanceof Error?searchError.message:'전화번호를 검색하지 못했습니다.')}}finally{if(requestAbort.current===controller){requestAbort.current=null;setLoading(false)}}};return <div className="phone-search"><form onSubmit={event=>{event.preventDefault();void search()}}><input aria-label="전화번호 전체 검색" inputMode="tel" autoComplete="off" value={phone} onChange={event=>{requestAbort.current?.abort();requestAbort.current=null;requestValue.current='';setPhone(event.target.value);setResults([]);setSearched(false);setError('')}} placeholder="전화번호 전체 10~11자리"/><button disabled={loading}>{loading?'검색 중…':'전화번호 검색'}</button></form>{error&&<small role="alert">{error}</small>}{searched&&results.length===0&&<small>일치하는 참가자가 없습니다.</small>}{results.length>0&&<div className="phone-search-results">{results.map(result=><button key={result.id} onClick={()=>onSelect(result.id)}><b>{result.name}</b><span>{result.id} · {result.member_status} · {result.masked_phone}</span><em>상세 보기 →</em></button>)}</div>}</div>}
function ContactButton({onClick}:{onClick:()=>void}){return <button type="button" className="text-button" onClick={onClick}>연락처 보기</button>}
function Table({children}:{children:React.ReactNode}){return <div className="data-panel"><table>{children}</table></div>}function Empty({text}:{text:string}){return <div className="empty"><span>⌕</span><p>{text}</p></div>}function Privacy(){return <section className="notice"><span>i</span><div><b>로컬 데이터 보호</b><p>데이터는 설정에 표시된 SQLite 파일에만 저장됩니다. 외장하드 분리 전 서버를 종료하세요.</p></div></section>}
